import sys
from typing import List, Tuple

def solve(n: int, m: int, d: int, physics: List[Tuple[int, int]], informatics: List[Tuple[int, int]]) -> int:
    physics.sort(reverse=True)
    informatics.sort(reverse=True)

    physics_prefix = [(0, 0)]
    for c, w in physics:
        physics_prefix.append((physics_prefix[-1][0] + c, physics_prefix[-1][1] + w))

    informatics_prefix = [(0, 0)]
    for c, w in informatics:
        informatics_prefix.append((informatics_prefix[-1][0] + c, informatics_prefix[-1][1] + w))

    max_significance = 0
    for i in range(len(physics) + 1):
        if physics_prefix[i][1] > d:
            break
        remaining_width = d - physics_prefix[i][1]
        j = binary_search(informatics_prefix, remaining_width)
        if j > 0:
            max_significance = max(max_significance, physics_prefix[i][0] + informatics_prefix[j][0])

    for j in range(len(informatics) + 1):
        if informatics_prefix[j][1] > d:
            break
        remaining_width = d - informatics_prefix[j][1]
        i = binary_search(physics_prefix, remaining_width)
        if i > 0:
            max_significance = max(max_significance, physics_prefix[i][0] + informatics_prefix[j][0])

    return max_significance

def binary_search(prefix: List[Tuple[int, int]], width: int) -> int:
    left, right = 0, len(prefix) - 1
    while left <= right:
        mid = (left + right) // 2
        if prefix[mid][1] <= width:
            left = mid + 1
        else:
            right = mid - 1
    return right

def main():
    n, m, d = map(int, sys.stdin.readline().split())
    physics = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]
    informatics = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]
    result = solve(n, m, d, physics, informatics)
    print(result)

if __name__ == "__main__":
    main()
